from pathlib import Path
from zipfile import ZipFile
import xml.etree.ElementTree as E
for p in sorted(Path('docs/kiertokirjeet').glob('*.docx')):
 print('\\nFILE',p)
 with ZipFile(p) as z:
  root=E.fromstring(z.read('word/document.xml'))
  ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
  for para in root.findall('.//w:p',ns):
   print(''.join(t.text or '' for t in para.findall('.//w:t',ns)))
for p in sorted(Path('docs/liitteet').glob('*.xlsx')):
 print('\\nFILE',p)
 with ZipFile(p) as z:
  ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
  ss=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   ss=[''.join(t.itertext()) for t in E.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',ns)]
  print(z.read('xl/workbook.xml').decode())
  for f in z.namelist():
   if f.startswith('xl/worksheets/sheet') and f.endswith('.xml'):
    print(f)
    for row in E.fromstring(z.read(f)).findall('.//s:row',ns):
     cells=[]
     for c in row.findall('s:c',ns):
      v=c.find('s:v',ns)
      val=v.text if v is not None else ''.join(c.find('s:is',ns).itertext()) if c.find('s:is',ns) is not None else ''
      if c.get('t')=='s':val=ss[int(val)]
      cells.append(c.get('r')+'='+val)
     print(' | '.join(cells))
